using Nivara.Silk;
using Nivara.Tests.NivaraTorch;
using NUnit.Framework;

namespace Nivara.Tests.Gpu;

/// <summary>
/// Pins the Silk (OpenCL) elementary / activation / normalization / GEMM kernels against the
/// PyTorch reference fixtures generated by <c>samples/NivaraTorch/gen_reference.py</c> (stored under
/// <c>samples/data/torch-comparison/</c>). Mirrors <see cref="SilkVisionTorchParityTests"/>.
/// Pure mul-add cells (gemm, add, add_bias) bit-exact where directly comparable; fused/leaning
/// cells (gemm_bias against PyTorch's fused accumulation) use tolerance along with
/// transcendental / norm cells.
/// </summary>
[TestFixture]
public sealed class SilkElementaryTorchParityTests
{
    static SilkRuntime Device()
    {
        try { return new SilkRuntime(); }
        catch { Assert.Ignore("No OpenCL GPU available; skipping Silk elementary Torch parity."); throw; }
    }

    static nint Upload(SilkRuntime silk, float[] data)
    {
        var buf = silk.Allocate(data.Length);
        silk.Upload(buf, data);
        return buf;
    }

    static void ReleaseAll(SilkRuntime silk, params nint[] bufs)
    {
        foreach (var b in bufs) silk.Release(b);
    }

    static void AssertBitsEqual(float[] expected, float[] actual, string? label = null)
    {
        Assert.That(actual.Length, Is.EqualTo(expected.Length),
            $"{label}: length mismatch {actual.Length} vs {expected.Length}");
        for (int i = 0; i < expected.Length; i++)
        {
            Assert.That(BitConverter.SingleToInt32Bits(actual[i]),
                Is.EqualTo(BitConverter.SingleToInt32Bits(expected[i])),
                $"{label}: bit mismatch at [{i}] expected={expected[i]:G9} actual={actual[i]:G9}");
        }
    }

    static float[] Transpose(float[] src, int rows, int cols)
    {
        var dst = new float[src.Length];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                dst[c * rows + r] = src[r * cols + c];
        return dst;
    }

    // ---- SiLU ---------------------------------------------------------------

    [Test]
    public void Silu_1D_MatchesPyTorch()
    {
        var input = TestHelpers.LoadBin("silu_1d_input.bin");
        var expected = TestHelpers.LoadBin("silu_1d_output.bin");

        using var silk = Device();
        nint si = Upload(silk, input);
        nint so = silk.Allocate(expected.Length);
        SilkLauncher.Silu(silk, si, so, expected.Length);
        silk.Finish();
        var actual = silk.Download(so, expected.Length);
        TestHelpers.AssertTensorEqual(expected, actual, label: "Silk Silu_1D");
        ReleaseAll(silk, si, so);
    }

    [Test]
    public void Silu_4D_MatchesPyTorch()
    {
        var input = TestHelpers.LoadBin("silu_4d_input.bin");
        var expected = TestHelpers.LoadBin("silu_4d_output.bin");

        using var silk = Device();
        nint si = Upload(silk, input);
        nint so = silk.Allocate(expected.Length);
        SilkLauncher.Silu(silk, si, so, expected.Length);
        silk.Finish();
        var actual = silk.Download(so, expected.Length);
        TestHelpers.AssertTensorEqual(expected, actual, label: "Silk Silu_4D");
        ReleaseAll(silk, si, so);
    }

    // ---- GeGLU (GELU) ------------------------------------------------------

    [Test]
    public void GeGlu_MatchesGeluExactFixture()
    {
        var geluInput = TestHelpers.LoadBin("gelu_exact_1d_input.bin");
        var expected = TestHelpers.LoadBin("gelu_exact_1d_output.bin");
        int intermediate = geluInput.Length;
        var input = new float[intermediate * 2];
        Array.Copy(geluInput, 0, input, 0, intermediate);
        for (int i = intermediate; i < input.Length; i++) input[i] = 1.0f;

        using var silk = Device();
        nint si = Upload(silk, input);
        nint so = silk.Allocate(expected.Length);
        SilkLauncher.GeGlu(silk, si, so, 1, intermediate);
        silk.Finish();
        var actual = silk.Download(so, expected.Length);
        TestHelpers.AssertTensorEqual(expected, actual, label: "Silk GeGlu");
        ReleaseAll(silk, si, so);
    }

