    // ---- Add (bit-exact) ---------------------------------------------------

    [Test]
    public void Add_BitExact()
    {
        int n = 128;
        var a = new float[n];
        var b = new float[n];
        var expected = new float[n];
        for (int i = 0; i < n; i++)
        {
            a[i] = i * 0.5f - 10.0f;
            b[i] = (i % 7) * 0.25f + (i % 3) * 0.125f;
            expected[i] = a[i] + b[i];
        }

        using var silk = Device();
        nint sa = Upload(silk, a);
        nint sb = Upload(silk, b);
        nint so = silk.Allocate(n);
        SilkLauncher.Add(silk, sa, sb, so, n);
        silk.Finish();
        var actual = silk.Download(so, n);
        AssertBitsEqual(expected, actual, "Silk Add");
        ReleaseAll(silk, sa, sb, so);
    }

