        var input = TestHelpers.LoadBin("linear_128_64_input.bin");
        var weight = TestHelpers.LoadBin("linear_128_64_weight.bin");
        var bias = TestHelpers.LoadBin("linear_128_64_bias.bin");
        var expected = TestHelpers.LoadBin("linear_128_64_output.bin");
        int inFeatures = 128;
        int outFeatures = 64;
        var b = Transpose(weight, outFeatures, inFeatures);

        using var silk = Device();
        nint sa = Upload(silk, input);
        nint sb = Upload(silk, b);
        nint sbias = Upload(silk, bias);
        nint so = silk.Allocate(expected.Length);
        SilkLauncher.GemmEpilogue(silk, SilkKernels.GemmBias, sa, sb, so, sbias, 1, inFeatures, outFeatures);
        silk.Finish();
        var actual = silk.Download(so, expected.Length);
        TestHelpers.AssertTensorEqual(expected, actual, label: "Silk GemmBias linear_128_64");
        ReleaseAll(silk, sa, sb, sbias, so);
    }

